.motion-sample {
  --ml-accent: #c6f66b;
  --ml-ink: #13210d;
  box-sizing: border-box;
  position: relative;
  display: grid;
  place-items: center;
  width: 104px;
  height: 68px;
  border-radius: 10px;
  color: var(--ml-ink);
  background: var(--ml-accent);
  font: 700 20px/1 system-ui, sans-serif;
}

@keyframes ml-checker-drift {
  from { background-position: 0 0; }
  to { background-position: 48px 48px; }
}
.motion-sample { width: 132px; height: 86px; background: repeating-conic-gradient(#415833 0% 25%, #263b20 0% 50%) 0 0 / 48px 48px; color: #e4f5d3; border: 1px solid #657e44; animation: ml-checker-drift 5s linear infinite; }

@media (prefers-reduced-motion: reduce) {
  .motion-sample {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
    filter: none !important;
    clip-path: none !important;
    letter-spacing: normal !important;
  }
  .motion-sample::before,
  .motion-sample::after {
    animation: none !important;
    transition: none !important;
  }
}

